import json
import os

workspace = "/home/USER/runs/paper/qwen-in-glm-hpl-u1/frozen/held-out-5/play/users/u042/system/state/workspace/programs"

with open(os.path.join(workspace, "task-e058cbaf.json"), 'r') as f:
    demos = json.load(f)

input_grid = demos[0]
expected_output = demos[1]

# For 14x14 with dividers at rows/cols 4, 9
# Physical regions:
# Cell row 0: rows 0-3
# Cell row 1: rows 5-8  
# Cell row 2: rows 10-13 (wait, that's only 4 rows)
# Actually looking at output, it seems the grid repeats patterns

def transform(grid):
    h, w = len(grid), len(grid[0])

    # Find dividers
    r_divs = {r for r in range(h) if all(grid[r][c] == 8 for c in range(w))}
    c_divs = {c for c in range(w) if all(grid[r][c] == 8 for r in range(h))}

    # Output with same divider positions
    result = [[8] * w for _ in range(h)]

    # Copy pattern from first (top-left) non-divider cell to all cells in each row
    # For row 0 (logical), pattern comes from grid[0:4, 0:4]
    # For row 1 (logical), pattern comes from grid[5:9, 0:4]
    # The pattern is then broadcast across all logical cells in that row

    # Get row of physical indices for each logical row
    def get_row_indices(r_idx):
        """Rows for logical row r_idx (0-based, r_idx=0 means topmost cell row)."""
        if r_idx == 0:
            return list(range(4))
        elif r_idx == 1:
            return list(range(5, 9))
        else:
            return list(range(10, 14))

    # Get column physical indices for each logical column  
    def get_col_indices(c_idx):
        """Cols for logical column c_idx (0-based, with dividers)"""
        if c_idx == 0:
            return list(range(4))
        elif c_idx == 1:
            return list(range(5, 9))
        else:
            return list(range(10, 14))

    for r_logical in range(4):  # 4 cell rows
        row_indices = get_row_indices(r_logical)

        # Get pattern from first cell in this row
        pattern = []
        for r in row_indices:
            pattern.append(grid[r][:4])

        # Broadcast pattern to all logical columns in this row
        for c_logical in range(4):  # 4 cell columns
            col_indices = get_col_indices(c_logical)
            for r in row_indices:
                for c in col_indices:
                    if 0 <= r < h and 0 <= c < w:
                        result[r][c] = pattern[r % 4][c % 4]

        # Restore dividers if needed
        for r in r_divs:
            for c in range(w):
                result[r][c] = 8
        for c in c_divs:
            for r in range(h):
                result[r][c] = 8

    return result

result = transform(input_grid)
print("Matches:", result == expected_output)
print("\nResult rows 0-3:")
